// F4 parse (for F5: change the 3 config lines)
const FORCE = 'buyer_power';
const DRIVERS = ['alternatives', 'switching_cost', 'price_sensitivity', 'in_house_option', 'buyer_concentration'];
const RESEARCH_NODE = 'F4 research';

const research = $(RESEARCH_NODE).first().json;
const citations = research.citations || (research.search_results || []).map(r => r.url) || [];
const raw = String($input.first().json.output || $input.first().json.text || '').replace(/```json|```/g, '').trim();
const txt = raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
let p;
try { p = JSON.parse(txt); }
catch (e) {
  try { p = JSON.parse(txt.replace(/,\s*([}\]])/g, '$1')); }
  catch (e2) { throw new Error(`${FORCE}: AI did not return valid JSON: ` + raw.slice(0, 200)); }
}

const LEVEL = { high: 2, medium: 1, low: 0 };
const byName = {};
for (const d of p.drivers || []) byName[String(d.driver || '').toLowerCase()] = d;

const drivers = DRIVERS.map(name => {
  const d = byName[name] || {};
  let rating = String(d.rating || 'unknown').toLowerCase();
  if (!(rating in LEVEL)) rating = 'unknown';
  let source = String(d.source || '').trim();
  const m = source.match(/^\[?(\d+)\]?$/);
  if (m && citations[Number(m[1]) - 1]) source = citations[Number(m[1]) - 1];
  const sourceOk = source === 'our data' || citations.includes(source);
  let reason = String(d.reason || '');
  if (rating !== 'unknown' && !sourceOk) { reason = `${reason} [source not in research, set to unknown]`; rating = 'unknown'; }
  return { driver: name, rating, reason, source: sourceOk ? source : '' };
});

// Overall rating is computed in code, not by the AI
const known = drivers.filter(d => d.rating !== 'unknown');
const avg = known.length ? known.reduce((s, d) => s + LEVEL[d.rating], 0) / known.length : null;
const overall = known.length < 2 ? 'unknown' : avg >= 1.4 ? 'high' : avg >= 0.7 ? 'medium' : 'low';

return [{ json: {
  run_id: $('Stats').first().json.run_id,
  force: FORCE,
  overall,
  known_drivers: known.length,
  drivers,
  summary: String(p.summary || ''),
  drivers_text: drivers.map(d => `${d.driver}: ${d.rating} – ${d.reason}${d.source ? ' (' + d.source + ')' : ''}`).join('\n'),
  citations,
} }];

