// Stats: builds the analysed company's profile text and counts facts from our own competitor data
const profRec = $('load profile').first().json;
const pf = profRec.fields || profRec;
let raw = {};
try { raw = JSON.parse(pf.profile_json || '{}'); } catch (e) { throw new Error('profile_json is not valid JSON'); }

const val = k => {
  const o = raw[k]; if (!o) return null;
  let v = o.value;
  if (v === null || v === undefined || v === '' || (Array.isArray(v) && !v.length)) return null;
  if (Array.isArray(v)) v = v.map(i => (i && typeof i === 'object') ? i.item : i).filter(Boolean);
  return v;
};
const show = v => Array.isArray(v) ? v.join('; ') : String(v);
const profile = {};
for (const k of Object.keys(raw)) profile[k] = val(k);
const profile_text = Object.entries(profile).filter(([, v]) => v !== null).map(([k, v]) => k + ': ' + show(v)).join('\n');

// Competitors from Airtable (works with flat or nested "fields" output)
const comps = $input.all().map(i => ({ id: i.json.id, ...(i.json.fields || i.json) }));
const isTrue = v => String(v && v.name ? v.name : v) === 'true';
// business type set by the judge after enrichment (software / service / logistics_provider / consultancy / other)
const btype = c => String(c.business_type && c.business_type.name ? c.business_type.name : (c.business_type || '')).toLowerCase();
const status = c => String(c.status && c.status.name ? c.status.name : c.status);

const count = (list, fn) => list.filter(fn).length;
const monthsAgo = d => d ? (Date.now() - new Date(d).getTime()) / (30.44 * 864e5) : Infinity;
const emp = comps.map(c => Number(c.employees)).filter(n => n > 0).sort((a, b) => a - b);
const median = emp.length ? emp[Math.floor(emp.length / 2)] : null;

const stats = {
  candidates_not_rejected: comps.length,
  verified: count(comps, c => status(c) === 'verified'),
  unsure: count(comps, c => status(c) === 'unsure'),
  rivals_true: count(comps, c => isTrue(c.verdict_rivalry)),
  substitutes_true: count(comps, c => isTrue(c.verdict_substitute)),
  new_entrants_true: count(comps, c => isTrue(c.verdict_new_entrant)),
  outsourced_services: count(comps, c => btype(c) === 'service' && isTrue(c.verdict_substitute)),
  large_players_1000plus: count(comps, c => Number(c.employees) >= 1000),
  funded_last_24_months: count(comps, c => monthsAgo(c.last_funding_date) <= 24),
  growing_20pct_12m: count(comps, c => Number(c.headcount_growth_12m) >= 0.2),
  median_employees: median,
};

// Platform owners: TMS/ERP/visibility platforms (or 1000+ employee software players) that hold supplier power in this market
// Platform owners: software platforms bought for something else (TMS / ERP / visibility) that also do this job as a module.
// Checked on what the company does (search summary + Apollo description + keywords), never on the judge's reasons.
const PLATFORM_RE = /\b(tms|erp|s\/4hana|dynamics 365|transportation management|transport management|visibility platform|supply chain execution)\b/i;
const anyForce = c => ['verdict_rivalry', 'verdict_substitute', 'verdict_new_entrant'].some(k => ['true', 'unsure'].includes(String(c[k] && c[k].name ? c[k].name : c[k])));
const focus = c => String(c.job_focus && c.job_focus.name ? c.job_focus.name : (c.job_focus || '')).toLowerCase();
const platform_owners = comps
  .filter(c => anyForce(c) && btype(c) === 'software' && focus(c) !== 'core'
    && (!Number(c.employees) || Number(c.employees) >= 100)
    && PLATFORM_RE.test((c.what_they_do || '') + ' ' + (c.apollo_description || '') + ' ' + (c.keywords_text || '')))
  .map(c => ({ id: c.id, name: c.name, employees: Number(c.employees) || null }));
const integrations = Array.isArray(profile.integrations_tech) ? profile.integrations_tech : (profile.integrations_tech ? [profile.integrations_tech] : []);

const stats_text = [
  'Competitors found (not rejected): ' + (stats.candidates_not_rejected) + ' (verified ' + (stats.verified) + ', unsure ' + (stats.unsure) + ')',
  'Direct rivals (judge true): ' + (stats.rivals_true),
  'Substitutes (judge true): ' + (stats.substitutes_true) + ', of which outsourced services: ' + (stats.outsourced_services),
  'New entrants (judge true): ' + (stats.new_entrants_true),
  'Large players with 1000+ employees: ' + (stats.large_players_1000plus),
  'Raised funding in the last 24 months: ' + (stats.funded_last_24_months),
  'Grew headcount 20%+ in 12 months: ' + (stats.growing_20pct_12m),
  'Median competitor size: ' + (median === null ? 'unknown' : median) + ' employees',
  'Integrations stated on its own website: ' + (integrations.join(', ') || 'none'),
  'Platform owners among competitors (TMS/ERP/visibility platforms with their own audit or spend module): ' + (platform_owners.length) + ' – ' + (platform_owners.map(p => p.name).join(', ') || 'none'),
].join('\n');

return [{ json: {
  run_id: pf.run_id,
  company_name: profile.company_name || pf.company_name || pf.domain,
  domain: pf.domain,
  category: profile.category || pf.category || '',
  profile_text, integrations, stats, stats_text, platform_owners,
} }];

