// F5 parse: supplier power, rated at market level
const FORCE = 'supplier_power';
const DRIVERS = ['data_access', 'integration_gatekeepers', 'supplier_concentration', 'forward_integration'];
const RESEARCH_NODE = 'F5 research1';
const STATS_NODE = 'Stats';

const research = $(RESEARCH_NODE).first().json;
const citations = research.citations || (research.search_results || []).map(r => r.url) || [];
const raw = String($input.first().json.output || $input.first().json.text || '').replace(/```json|```/g, '').trim();
const txt = raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
let p;
try { p = JSON.parse(txt); }
catch (e) {
  try { p = JSON.parse(txt.replace(/,\s*([}\]])/g, '$1')); }
  catch (e2) { throw new Error(`${FORCE}: AI did not return valid JSON: ` + raw.slice(0, 200)); }
}

const LEVEL = { high: 2, medium: 1, low: 0 };
const byName = {};
for (const d of p.drivers || []) byName[String(d.driver || '').toLowerCase()] = d;

const drivers = DRIVERS.map(name => {
  const d = byName[name] || {};
  let rating = String(d.rating || 'unknown').toLowerCase();
  if (!(rating in LEVEL)) rating = 'unknown';
  let source = String(d.source || '').trim();
  const m = source.match(/^\[?(\d+)\]?$/);
  if (m && citations[Number(m[1]) - 1]) source = citations[Number(m[1]) - 1];
  const sourceOk = source === 'our data' || citations.includes(source);
  let reason = String(d.reason || '');
  if (rating !== 'unknown' && !sourceOk) { reason = `${reason} [source not in research, set to unknown]`; rating = 'unknown'; }
  return { driver: name, rating, reason, source: sourceOk ? source : '' };
});

// Overall rating is computed in code, not by the AI
const known = drivers.filter(d => d.rating !== 'unknown');
const avg = known.length ? known.reduce((s, d) => s + LEVEL[d.rating], 0) / known.length : null;
const overall = known.length < 2 ? 'unknown' : avg >= 1.4 ? 'high' : avg >= 0.7 ? 'medium' : 'low';

return [{ json: {
  run_id: $(STATS_NODE).first().json.run_id,
  force: FORCE,
  overall,
  known_drivers: known.length,
  drivers,
  summary: String(p.summary || ''),
  drivers_text: drivers.map(d => `${d.driver}: ${d.rating} – ${d.reason}${d.source ? ' (' + d.source + ')' : ''}`).join('\n'),
  citations,
  platform_owners: $(STATS_NODE).first().json.platform_owners,
} }];

// Score + rank: fixed rules, every number explainable
const STATS_NODE = 'Stats';
const FORCES_NODE = 'Forces';
// read ALL rows from Get competitors and filter in code (no dependence on which If branch carries the run)
const COMPETITORS_NODE = 'Get competitors';

// 1. Force weights from F4 (buyer power) and F5 (supplier power)
const forces = {};
for (const it of $(FORCES_NODE).all()) if (it.json.force) forces[it.json.force] = it.json;
const buyer = forces.buyer_power || { overall: 'unknown', drivers: [] };
const supplier = forces.supplier_power || { overall: 'unknown', drivers: [] };
const driver = (f, name) => ((f.drivers || []).find(d => d.driver === name) || {}).rating || 'unknown';

const W = { rivalry: 1.0, substitute: 0.8, new_entrant: 0.6 };
const rules = [];
if (buyer.overall === 'high') { W.rivalry += 0.1; W.substitute += 0.2; rules.push('buyer power high: rivalry +0.1, substitute +0.2'); }
if (buyer.overall === 'medium') { W.substitute += 0.1; rules.push('buyer power medium: substitute +0.1'); }
if (driver(buyer, 'switching_cost') === 'high') { W.new_entrant += 0.2; rules.push('switching cost low (buyer power high): new_entrant +0.2'); }
// capped at x1.1: one AI rating of supplier power must not move a company by 20%
const PLATFORM_MULT = supplier.overall === 'high' || supplier.overall === 'medium' ? 1.1 : 1.0;
if (PLATFORM_MULT > 1) rules.push('supplier power ' + supplier.overall + ': platform owners x' + PLATFORM_MULT);
const MAX_R = 1.2;
// job focus: how central the analysed company's job is to this competitor (from the judge)
const FOCUS = { core: 1.0, major_module: 0.8, minor_feature: 0.5, unknown: 0.8 };

// 2. Helpers
const sel = v => String(v && v.name ? v.name : (v === null || v === undefined ? '' : v)).toLowerCase();
const clamp = x => Math.max(0, Math.min(1, x));
const monthsAgo = d => d ? (Date.now() - new Date(d).getTime()) / (30.44 * 864e5) : Infinity;
const platformIds = new Set(($(STATS_NODE).first().json.platform_owners || []).map(p => p.id));
const r2 = x => Math.round(x * 100) / 100;

// 3. Score every competitor
const RUN_ID = $(STATS_NODE).first().json.run_id;
if (!RUN_ID) throw new Error('No run_id from Stats');
const runRows = $(COMPETITORS_NODE).all()
  .map(i => ({ id: i.json.id, ...(i.json.fields || i.json) }))
  .filter(c => c.run_id === RUN_ID);
if (!runRows.length) throw new Error('No competitors found for ' + RUN_ID);
const comps = runRows.filter(c => sel(c.status) !== 'rejected' && sel(c.status) !== 'candidate');
// rows the judge could not rate (status still "candidate") are not scored, only listed
const judge_failed = runRows.filter(c => sel(c.status) === 'candidate').map(c => c.name);

// 3. Market presence: is the competitor present in the analysed company's focus market?
// local = HQ in the market · active = HQ elsewhere, but market domain or own website pages in the market language
// none = clear data, no presence found · unknown = no HQ data (never penalised)
const PROFILE_NODE = 'load profile';
const SITE_NODE = 'Site signals';
const MARKETS = {
  'DACH': { c: ['DE', 'AT', 'CH'], lang: 'de' }, 'Germany': { c: ['DE'], lang: 'de' }, 'Austria': { c: ['AT'], lang: 'de' },
  'Switzerland': { c: ['CH'], lang: 'de' }, 'UK & Ireland': { c: ['GB', 'IE'], lang: '' }, 'France': { c: ['FR'], lang: 'fr' },
  'Benelux': { c: ['NL', 'BE', 'LU'], lang: 'nl' }, 'Nordics': { c: ['SE', 'DK', 'NO', 'FI'], lang: 'sv' },
  'Southern Europe': { c: ['ES', 'IT', 'PT'], lang: 'es' }, 'Central & Eastern Europe': { c: ['PL', 'CZ', 'RO', 'HU'], lang: 'pl' },
  'EU': { c: ['DE', 'FR', 'NL', 'GB', 'ES', 'IT'], lang: '' }, 'North America': { c: ['US', 'CA'], lang: '' },
  'United States': { c: ['US'], lang: '' }, 'Latin America': { c: ['BR', 'MX', 'AR', 'CO'], lang: 'es' },
  'Middle East & Africa': { c: ['AE', 'SA', 'TR', 'ZA'], lang: '' }, 'India': { c: ['IN'], lang: '' },
  'Asia-Pacific': { c: ['SG', 'AU', 'JP', 'IN'], lang: '' }, 'Global': { c: [], lang: '' }
};
const COUNTRY = { DE: 'germany', AT: 'austria', CH: 'switzerland', GB: 'united kingdom', IE: 'ireland', FR: 'france',
  NL: 'netherlands', BE: 'belgium', LU: 'luxembourg', SE: 'sweden', DK: 'denmark', NO: 'norway', FI: 'finland',
  ES: 'spain', IT: 'italy', PT: 'portugal', PL: 'poland', CZ: 'czech', RO: 'romania', HU: 'hungary', US: 'united states',
  CA: 'canada', BR: 'brazil', MX: 'mexico', AR: 'argentina', CO: 'colombia', AE: 'united arab emirates', SA: 'saudi arabia',
  TR: 'turk', ZA: 'south africa', IN: 'india', SG: 'singapore', AU: 'australia', JP: 'japan' };
const LANG_WORDS = {
  de: /\b(und|der|die|das|für|mit|ihre|ihren|unsere|wir|sie|rechnung|rechnungen|frachtkosten|versand|kosten|prüfung)\b/gi,
  fr: /\b(et|les|des|pour|avec|vos|nous|facture|factures|coûts)\b/gi,
  nl: /\b(en|het|voor|met|uw|wij|factuur|facturen|kosten)\b/gi,
  es: /\b(y|los|las|para|con|sus|nuestro|factura|facturas|costes|costos)\b/gi,
  sv: /\b(och|för|med|våra|vi|faktura|fakturor|kostnader)\b/gi,
  pl: /\b(dla|oraz|nasze|faktura|faktury|koszty)\b/gi
};
let focusMarket = '';
try { const pr = $(PROFILE_NODE).first().json; const pf = pr.fields || pr; focusMarket = String(pf.focus_market && pf.focus_market.name ? pf.focus_market.name : (pf.focus_market || '')); } catch (e) {}
const MK = MARKETS[focusMarket] || MARKETS['Global'];
const MARKET_ON = MK.c.length > 0;
const NO_PRESENCE_MULT = 0.8;
const tlds = MK.c.map(x => x === 'GB' ? '.uk' : '.' + x.toLowerCase());
const host = u => { const m = String(u || '').match(/^https?:\/\/(?:www\.)?([^\/\s]+)/i); return m ? m[1].toLowerCase() : ''; };
// results of the website check; empty when the check did not run
let SITE = {};
try { SITE = $(SITE_NODE).first().json.signals || {}; } catch (e) {}
const marketPresence = c => {
  if (!MARKET_ON) return { label: 'n/a', note: 'no focus market' };
  const country = String(c.hq_country || '').toLowerCase();
  if (country && MK.c.some(x => country.includes(COUNTRY[x]))) return { label: 'local', note: 'HQ ' + [c.hq_city, c.hq_country].filter(Boolean).join(', ') };
  const dom = String(c.domain || host(c.website_url) || '').toLowerCase();
  if (dom && tlds.some(t => dom.endsWith(t))) return { label: 'active', note: 'market domain ' + dom };
  // website check (Site signals): hreflang, market pages, market subdomain or market domain
  const site = SITE[c.id];
  if (site && site.found) return { label: 'active', note: site.note };
  if (MK.lang && dom) {
    const re = LANG_WORDS[MK.lang];
    for (const l of String(c.evidence_text || '').split('\n')) {
      const m = l.match(/"(.+)"\s*-\s*(https?:\S+)/);
      if (!m) continue;
      const h = host(m[2]);
      const own = h === dom || h.endsWith('.' + dom);
      const words = new Set((m[1].match(re) || []).map(w => w.toLowerCase()));
      if (own && words.size >= 2) return { label: 'active', note: 'own website page in the market language (' + h + ')' };
    }
  }
  if (!country) return { label: 'unknown', note: 'no HQ data' };
  const checked = site && site.checked ? ', website checked' : '';
  return { label: 'none', note: 'HQ ' + c.hq_country + ', no ' + focusMarket + ' signal found' + checked };
};

const rows = comps.map(c => {
  // Relevance: best force weight (true = full, unsure = half) + 0.1 per extra true force
  const v = { rivalry: sel(c.verdict_rivalry), substitute: sel(c.verdict_substitute), new_entrant: sel(c.verdict_new_entrant) };
  const parts = Object.entries(v).map(([f, x]) => x === 'true' ? W[f] : x === 'unsure' ? W[f] * 0.5 : 0);
  const trueCount = Object.values(v).filter(x => x === 'true').length;
  const focus = sel(c.job_focus) || 'unknown';
  const F = FOCUS[focus] !== undefined ? FOCUS[focus] : FOCUS.unknown;
  // relevance counts only as much as the job is central to them
  const R = clamp((Math.max(...parts) + 0.1 * Math.max(0, trueCount - 1)) / MAX_R) * F;

  // Size: employees (log) 60% + funding (log) 40%; funding unknown -> employees only; both unknown -> 0.25
  const emp = Number(c.employees) || 0;
  const usd = Number(c.funding_total_usd) || 0;
  const eS = emp > 0 ? clamp(Math.log10(emp) / 4) : null;
  const fS = usd > 0 ? clamp(Math.log10(usd) / 9) : null;
  // size unknown (no company data) is left out of the score instead of counting as "small"
  let S = null;
  if (eS !== null && fS !== null) S = 0.6 * eS + 0.4 * fS;
  else if (eS !== null) S = eS;
  else if (fS !== null) S = fS;

  // Momentum: headcount growth 12m 60% (ignored under 20 employees) + funding recency 40%
  const g = (emp >= 20 && c.headcount_growth_12m !== undefined && c.headcount_growth_12m !== null) ? clamp(Number(c.headcount_growth_12m) / 0.5) : null;
  const m = monthsAgo(c.last_funding_date);
  const rec = m <= 12 ? 1 : m <= 24 ? 0.5 : 0;
  // momentum also counts only as much as the job is central (funding for another product is not a threat here)
  const M = (g !== null ? 0.6 * g + 0.4 * rec : rec) * F;

  // Confidence and platform multiplier
  const C = sel(c.status) === 'verified' ? 1.0 : 0.7;
  const isPlatform = platformIds.has(c.id);
  const mult = isPlatform ? PLATFORM_MULT : 1;

  // what a company does (relevance) counts more than how big or fast-growing it is
  const base = S === null ? (0.6 * R + 0.2 * M) / 0.8 : 0.6 * R + 0.2 * S + 0.2 * M;
  const mp = marketPresence(c);
  const marketMult = mp.label === 'none' ? NO_PRESENCE_MULT : 1;
  const score = Math.min(100, Math.round(100 * C * base * mult * marketMult * 10) / 10);
  const notes = [];
  if (marketMult < 1) notes.push('no presence in ' + focusMarket + ' found: x' + NO_PRESENCE_MULT);
  // a clearly different customer segment (checked in the judge) can never be a primary threat
  const otherSegment = sel(c.segment_match) === 'different';
  if (otherSegment) notes.push('different customer segment: capped at Watch');
  if (S === null) notes.push('size unknown, not counted');
  if (emp > 0 && emp < 20) notes.push('growth ignored (<20 employees)');
  return {
    id: c.id, name: c.name, score, platform_owner: isPlatform,
    market_presence: mp.label, market_note: mp.note,
    tier: score >= 70 && !otherSegment ? 'Primary threat' : score >= 50 ? 'Watch' : 'Peripheral',
    score_breakdown: 'R ' + r2(R) + ' (focus ' + focus + ' x' + F + ') · S ' + (S === null ? '-' : r2(S)) + ' · M ' + r2(M) + ' · C ' + C + (isPlatform ? ' · platform x' + mult : '') + (notes.length ? ' (' + notes.join(', ') + ')' : ''),
  };
});

rows.sort((a, b) => b.score - a.score);
rows.forEach((r, i) => { r.rank = i + 1; });

if (MARKET_ON) rules.push('focus market ' + focusMarket + ': no presence found x' + NO_PRESENCE_MULT);
const weights_text = 'Weights: rivalry ' + r2(W.rivalry) + ', substitute ' + r2(W.substitute) + ', new_entrant ' + r2(W.new_entrant) + '. ' + (rules.join('; ') || 'no adjustments');
return rows.map((r, i) => ({ json: i === 0 ? { ...r, weights_text, judge_failed } : r }));

// Site check list: which competitors need a website check for the focus market?
// Only companies whose HQ is NOT in the market and whose domain is not a market domain.
// Local companies and market domains are already clear, so they are skipped.
const STATS_NODE = 'Stats';
const COMPETITORS_NODE = 'Get competitors';
const PROFILE_NODE = 'load profile';

// focus market -> country codes + language code (same keys as the form)
const MARKETS = {
  'DACH': { c: ['DE', 'AT', 'CH'], lang: 'de' }, 'Germany': { c: ['DE'], lang: 'de' }, 'Austria': { c: ['AT'], lang: 'de' },
  'Switzerland': { c: ['CH'], lang: 'de' }, 'UK & Ireland': { c: ['GB', 'IE'], lang: '' }, 'France': { c: ['FR'], lang: 'fr' },
  'Benelux': { c: ['NL', 'BE', 'LU'], lang: 'nl' }, 'Nordics': { c: ['SE', 'DK', 'NO', 'FI'], lang: 'sv' },
  'Southern Europe': { c: ['ES', 'IT', 'PT'], lang: 'es' }, 'Central & Eastern Europe': { c: ['PL', 'CZ', 'RO', 'HU'], lang: 'pl' },
  'EU': { c: ['DE', 'FR', 'NL', 'GB', 'ES', 'IT'], lang: '' }, 'North America': { c: ['US', 'CA'], lang: '' },
  'United States': { c: ['US'], lang: '' }, 'Latin America': { c: ['BR', 'MX', 'AR', 'CO'], lang: 'es' },
  'Middle East & Africa': { c: ['AE', 'SA', 'TR', 'ZA'], lang: '' }, 'India': { c: ['IN'], lang: '' },
  'Asia-Pacific': { c: ['SG', 'AU', 'JP', 'IN'], lang: '' }, 'Global': { c: [], lang: '' }
};
const COUNTRY = { DE: 'germany', AT: 'austria', CH: 'switzerland', GB: 'united kingdom', IE: 'ireland', FR: 'france',
  NL: 'netherlands', BE: 'belgium', LU: 'luxembourg', SE: 'sweden', DK: 'denmark', NO: 'norway', FI: 'finland',
  ES: 'spain', IT: 'italy', PT: 'portugal', PL: 'poland', CZ: 'czech', RO: 'romania', HU: 'hungary', US: 'united states',
  CA: 'canada', BR: 'brazil', MX: 'mexico', AR: 'argentina', CO: 'colombia', AE: 'united arab emirates', SA: 'saudi arabia',
  TR: 'turk', ZA: 'south africa', IN: 'india', SG: 'singapore', AU: 'australia', JP: 'japan' };

const sel = v => String(v && v.name ? v.name : (v === null || v === undefined ? '' : v)).toLowerCase();
const host = u => { const m = String(u || '').match(/^(?:https?:\/\/)?(?:www\.)?([^\/\s?#]+)/i); return m ? m[1].toLowerCase() : ''; };

let focusMarket = '';
try { const pr = $(PROFILE_NODE).first().json; const pf = pr.fields || pr; focusMarket = String(pf.focus_market && pf.focus_market.name ? pf.focus_market.name : (pf.focus_market || '')); } catch (e) {}
const MK = MARKETS[focusMarket] || MARKETS['Global'];
if (!MK.c.length) return [];   // no focus market -> nothing to check

const tlds = MK.c.map(x => x === 'GB' ? '.uk' : '.' + x.toLowerCase());
// path / subdomain codes we accept as a market version of the site: language + country codes (DACH: de, at, ch)
const codes = [...new Set([MK.lang, ...MK.c.map(x => x.toLowerCase())].filter(Boolean))];

const RUN_ID = $(STATS_NODE).first().json.run_id;
const rows = $(COMPETITORS_NODE).all()
  .map(i => ({ id: i.json.id, ...(i.json.fields || i.json) }))
  .filter(c => c.run_id === RUN_ID && !['rejected', 'candidate'].includes(sel(c.status)));

const out = [];
for (const c of rows) {
  const country = String(c.hq_country || '').toLowerCase();
  if (country && MK.c.some(x => country.includes(COUNTRY[x]))) continue;      // local: already clear
  const dom = host(c.domain || c.website_url);
  if (!dom) continue;                                                          // no website to check
  if (tlds.some(t => dom.endsWith(t))) continue;                               // market domain: already clear
  out.push({ json: { id: c.id, name: c.name, domain: dom, url: 'https://' + dom, codes, tlds, lang: MK.lang } });
}
return out;

// Site signals: does the homepage show a version for the focus market?
// Signals (any one is enough): hreflang tag, html lang, own link to a market path (/de/, /de-at/),
// market subdomain (de.brand.com) or own market domain (brand.de). Pure code, no AI.
const LIST_NODE = 'Site check list';
const list = $(LIST_NODE).all();
const res = $input.all();

const host = u => { const m = String(u || '').match(/^https?:\/\/(?:www\.)?([^\/\s?#"']+)/i); return m ? m[1].toLowerCase() : ''; };
const signals = {};
const failed = [];

list.forEach((it, i) => {
  const c = it.json;
  if (!c.id) return;                       // empty item (nothing to check)
  const r = res[i] ? res[i].json : {};
  const status = Number(r.statusCode) || 0;
  const raw = r.html || r.data || r.body || '';
  const html = String(typeof raw === 'string' ? raw : JSON.stringify(raw)).toLowerCase();
  if (!html || html.length < 200 || r.error || status >= 400) { failed.push(c.name); signals[c.id] = { found: false, checked: false, note: 'website not reachable' + (status ? ' (HTTP ' + status + ')' : '') }; return; }

  const codes = c.codes || [];
  const tlds = c.tlds || [];
  const dom = c.domain;
  const stem = dom.split('.')[0];
  const codeRe = '(?:' + codes.join('|') + ')(?:-[a-z]{2})?';
  let note = '';

  // 1. hreflang="de" / "de-at" / "de-ch"
  if (codes.length && new RegExp('hreflang\\s*=\\s*["\']?' + codeRe + '["\'\\s/>]').test(html)) note = 'hreflang ' + codes[0] + ' on ' + dom;
  // 2. page itself is in the market language
  else if (c.lang && new RegExp('<html[^>]*\\slang\\s*=\\s*["\']?' + c.lang + '(?:-[a-z]{2})?["\'\\s>]').test(html)) note = 'homepage in the market language (' + dom + ')';
  else {
    // 3./4./5. links: own market path, market subdomain or own market domain
    const hrefs = html.match(/href\s*=\s*["'][^"']+["']/g) || [];
    for (const h of hrefs) {
      const u = h.replace(/^href\s*=\s*["']/, '').replace(/["']$/, '');
      const hh = host(u);
      const own = !hh || hh === dom || hh.endsWith('.' + dom);
      const path = hh ? u.replace(/^https?:\/\/[^\/]+/i, '') : u;
      if (own && new RegExp('^/' + codeRe + '(?:/|$|\\?|#)').test(path)) { note = 'market page ' + (hh || dom) + path.split(/[?#]/)[0]; break; }
      if (hh && codes.some(k => hh === k + '.' + dom)) { note = 'market subdomain ' + hh; break; }
      if (hh && hh.split('.')[0] === stem && tlds.some(t => hh.endsWith(t))) { note = 'own market domain ' + hh; break; }
    }
  }
  signals[c.id] = note ? { found: true, checked: true, note } : { found: false, checked: true, note: 'website checked, no market version found' };
});

return [{ json: { signals, checked: list.filter(x => x.json.id).length, active: Object.values(signals).filter(s => s.found).length, failed } }];

// Check saved forces: was buyer and supplier power already researched for this run?
// Yes -> reuse the saved ratings (same run = same scores, no new search).
// No  -> research once (F4 + F5) and save.
// To force new research for a run: delete its 2 rows in Force Assessments.
const stats = $('Stats').first().json;
const sel = v => String(v && v.name ? v.name : (v === null || v === undefined ? '' : v));

const saved = $input.all()
  .map(i => i.json.fields || i.json)
  .filter(f => f.run_id === stats.run_id && f.overall && f.drivers_json);

const forces = {};
for (const f of saved) {
  let drivers = [];
  try { drivers = JSON.parse(f.drivers_json); } catch (e) { continue; }   // broken row -> research again
  forces[sel(f.force)] = {
    run_id: f.run_id,
    force: sel(f.force),
    overall: sel(f.overall),
    known_drivers: Number(f.known_drivers) || drivers.filter(d => d.rating !== 'unknown').length,
    drivers,
    summary: f.summary || '',
    drivers_text: f.drivers_text || '',
    citations: String(f.citations_text || '').split('\n').filter(Boolean),
  };
}
const cached = !!(forces.buyer_power && forces.supplier_power);

// pass the Stats data on: the research nodes read company_name, domain, profile_text from it
return [{ json: { ...stats, cached, saved_forces: cached ? [forces.buyer_power, forces.supplier_power] : [] } }];

// Forces: one place that holds buyer and supplier power for scoring
// new research (Merge1 ran) or the saved ratings of this run (Check saved forces)
let items = [];
let source = 'saved';
let ran = false;
try { ran = $('Merge1').isExecuted; } catch (e) {}
if (ran) {
  items = $('Merge1').all().map(i => i.json).filter(j => j.force);
  source = 'new research';
} else {
  items = $('Check saved forces').first().json.saved_forces || [];
}
if (items.length < 2) throw new Error('Buyer or supplier power missing (' + source + ')');
return items.map(j => ({ json: { ...j, forces_source: source } }));
